import {money,cents,monthShift,monthName,monthEnd,dayInMonth,cashTotals,reserves,today,invoices} from './finance.mjs';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const palette=['#2563eb','#059669','#7c3aed','#f59e0b','#e53945','#0891b2','#db2777','#64748b'];
export const sum=rows=>rows.reduce((s,x)=>s+cents(x.valor),0)/100;
export const shortMonth=m=>new Intl.DateTimeFormat('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}).format(new Date(m+'-01T12:00:00Z')).replace('.','');
export function monthsTo(end,n=6){return Array.from({length:n},(_,i)=>monthShift(end,i-n+1));}
export function rangeFor(m,cutoff=31){return [m+'-01',dayInMonth(m,cutoff)];}
export function dated(rows,start,end,basis='cash') {return rows.filter(x=>x.status!=='cancelado'&&(basis==='cash'?x.status==='concluido':true)&&((basis==='cash'?x.data_realizada:x.data_prevista)||'')>=start&&((basis==='cash'?x.data_realizada:x.data_prevista)||'')<=end);}
export function groupAmounts(rows,key){const map=new Map();for(const r of rows){const k=key(r);map.set(k,(map.get(k)||0)+cents(r.valor));}return [...map].map(([name,value])=>({name,value:value/100})).sort((a,b)=>b.value-a.value);}
export function change(a,b){const d=Math.round((a-b)*100)/100;return `${d>0?'+':''}${money(d)} · ${b===0?(a===0?'sem variação':'sem base percentual'):(d>0?'+':'')+(d/Math.abs(b)*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'}`;}
export function cashSeries(rows,months,cutoff=31){return months.map(m=>({key:m,label:shortMonth(m),...cashTotals(rows,...rangeFor(m,cutoff))}));}
export function recurringDate(start,i,freq='mensal'){if(['semanal','quinzenal'].includes(freq)){const d=new Date(start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i*(freq==='semanal'?7:14));return d.toISOString().slice(0,10);}return dayInMonth(monthShift(start.slice(0,7),i*(freq==='anual'?12:freq==='trimestral'?3:1)),Number(start.slice(8)));}
export function seriesChart(data,series,{line=false,id='chart',title='Comparação',detail=true}={}){
 if(!data.length||!data.some(d=>series.some(s=>Number(d[s.key]))))return '<div class="chart-empty">Nenhum valor registrado neste período.</div>';
 const W=Math.max(560,data.length*70+70),H=280,L=66,R=14,T=18,B=44,inner=W-L-R,height=H-T-B;
 const values=data.flatMap(d=>series.map(s=>Number(d[s.key])||0)),max=Math.max(1,...values),min=Math.min(0,...values),span=max-min,y=v=>T+(max-v)/span*height,slot=inner/data.length;
 let svg=`<svg class="plot" viewBox="0 0 ${W} ${H}" style="min-width:${data.length>8?W:480}px" role="img" aria-label="${esc(title)}">`;
 for(let i=0;i<5;i++){const v=min+span*i/4,yy=y(v);svg+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#dfe6ef" stroke-dasharray="3 4"/><text x="${L-10}" y="${yy+5}" text-anchor="end" fill="#63718a" font-size="13">${esc(v.toLocaleString('pt-BR',{maximumFractionDigits:0}))}</text>`;}
 svg+=`<line x1="${L}" y1="${y(0)}" x2="${W-R}" y2="${y(0)}" stroke="#c5cfdd"/>`;
 series.forEach((s,si)=>{const points=data.map((d,i)=>[L+slot*(i+.5),y(Number(d[s.key])||0)]);if(line)svg+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${s.color}" stroke-width="3"/>`;data.forEach((d,i)=>{const value=Number(d[s.key])||0,xx=L+slot*(i+.5),yy=y(value),attrs=detail?`role="button" tabindex="0" data-drill="${id}" data-index="${i}" data-series="${s.key}" aria-label="${esc(d.label+' · '+s.name+' · '+money(value))}"`:'';svg+=`<g ${attrs}><title>${esc(d.label+' · '+s.name+': '+money(value))}</title>`;if(line)svg+=`<circle cx="${xx}" cy="${yy}" r="5" fill="${s.color}"/>`;else{const bw=Math.min(25,slot*.75/series.length),x=xx+(si-series.length/2)*bw;svg+=`<rect x="${x}" y="${Math.min(yy,y(0))}" width="${bw-3}" height="${Math.max(2,Math.abs(y(0)-yy))}" rx="3" fill="${s.color}"/>`;}svg+='</g>';});});
 data.forEach((d,i)=>{svg+=`<text x="${L+slot*(i+.5)}" y="${H-15}" text-anchor="middle" font-size="13" fill="#52617b">${esc(d.label)}</text>`;});svg+='</svg>';
 return `<div class="plot-scroll">${svg}</div><div class="plot-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('')}</div><details class="chart-data"><summary>Ver valores em tabela</summary><div class="tablewrap"><table><thead><tr><th>Período</th>${series.map(s=>`<th>${esc(s.name)}</th>`).join('')}</tr></thead><tbody>${data.map(d=>`<tr><td>${esc(d.label)}</td>${series.map(s=>`<td>${money(d[s.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
export const cashKeys=[{key:'income',name:'Entradas recebidas',color:'#059669'},{key:'expense',name:'Saídas pagas',color:'#e53945'}];
export function donut(groups,id='category'){
 const total=groups.reduce((s,g)=>s+g.value,0);if(!total)return '<div class="chart-empty">As categorias aparecerão após os primeiros lançamentos.</div>';
 const shown=groups.slice(0,5);if(groups.length>5)shown.push({name:'Outras categorias',value:groups.slice(5).reduce((s,x)=>s+x.value,0),other:true});let offset=0;const radius=76,circ=2*Math.PI*radius;
 const arcs=shown.map((g,i)=>{const len=g.value/total*circ;const out=`<circle cx="110" cy="110" r="${radius}" fill="none" stroke="${palette[i]}" stroke-width="27" stroke-dasharray="${len} ${circ-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"/>`;offset+=len;return out;}).join('');
 return `<div class="donut-layout"><svg viewBox="0 0 220 220" role="img" aria-label="Distribuição por categoria, total ${esc(money(total))}">${arcs}<text x="110" y="108" text-anchor="middle" font-size="19" font-weight="700" fill="#132440">${esc(money(total))}</text><text x="110" y="133" text-anchor="middle" font-size="13" fill="#66758d">total no período</text></svg><div class="donut-legend">${shown.map((g,i)=>`<button class="legend-row" data-drill="${id}" data-index="${i}" aria-label="Ver ${esc(g.name)}"><i style="background:${palette[i]}"></i><span>${esc(g.name)}<b>${money(g.value)}</b></span><strong>${(g.value/total*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}%</strong></button>`).join('')}</div></div>`;
}
export function pairedGroups(rows,a,b,labels=['Mês selecionado','Comparação']){
 const max=Math.max(1,...rows.flatMap(g=>[g.a,g.b]));return `<div class="pair-legend"><span><i style="background:#2563eb"></i>${esc(labels[0])}</span><span><i style="background:#94a3b8"></i>${esc(labels[1])}</span></div>`+rows.map((g,i)=>`<button class="pair-row" data-drill="compare" data-index="${i}"><span class="pair-title"><b>${esc(g.name)}</b><small>${esc(change(g.a,g.b))}</small></span><span class="pair-track"><i style="width:${g.a/max*100}%;background:#2563eb"></i><b>${money(g.a)}</b></span><span class="pair-track"><i style="width:${g.b/max*100}%;background:#94a3b8"></i><b>${money(g.b)}</b></span></button>`).join('');
}
export function mountAnalytics(host,ctx){
 const {D,rows,month,scopeName,categoryName,showRecords,initialPerson='all'}=ctx;
 host.innerHTML=`<section class="panel analysis-controls"><div class="filters"><label>Analisar<select id="analysis-kind"><option value="cash">Entradas e saídas</option><option value="categories">Categorias entre meses</option><option value="evolution">Evolução de uma categoria</option><option value="sources">Fontes de receitas</option><option value="people">David, Carol e família</option><option value="cards">Faturas futuras</option><option value="budgets">Orçamento e gastos</option><option value="goals">Objetivos e investimentos</option></select></label><label>Mês principal<input id="analysis-month" type="month" value="${month}"></label><label>Comparar com<input id="analysis-compare" type="month" value="${monthShift(month,-1)}"></label><label>Atalho<select id="analysis-preset"><option value="previous">Mês anterior</option><option value="year">Mesmo mês do ano anterior</option><option value="custom">Escolher meses</option></select></label><label>Histórico<select id="analysis-count"><option value="3">3 meses</option><option value="6" selected>6 meses</option><option value="12">12 meses</option></select></label><label>De quem é?<select id="analysis-person"><option value="all">Todos</option>${D.pessoas.map(p=>`<option value="${esc(p.id)}">${esc(p.nome)}</option>`).join('')}<option value="">Família</option></select></label><label>Categoria / fonte<select id="analysis-category"><option value="">Todas</option>${D.categorias.map(c=>`<option value="${esc(c.id)}">${esc(c.nome)} (${c.tipo==='entrada'?'entrada':'saída'})</option>`).join('')}</select></label><label>Gráfico<select id="analysis-style"><option value="bars">Barras</option><option value="lines">Linhas</option></select></label></div><label class="checkline"><input type="checkbox" id="analysis-cutoff" checked> Comparar até o mesmo dia, se o mês principal estiver em andamento</label></section><section class="panel analysis-result"><h2 id="analysis-title"></h2><p id="analysis-note" class="report-note"></p><div id="analysis-stats" class="comparison-stats"></div><div id="analysis-plot"></div><div id="analysis-extra"></div></section>`;
 const q=id=>host.querySelector('#analysis-'+id);q('person').value=initialPerson;let drills={};
 function run(){const m=q('month').value,b=q('compare').value;if(!m||!b)return;const kind=q('kind').value,person=q('person').value,cat=q('category').value,n=Number(q('count').value),cut=q('cutoff').checked&&m===today().slice(0,7)?Number(today().slice(8)):31,months=monthsTo(m,n),base=rows.filter(x=>(person==='all'||(x.pessoa_id||'')===person)&&(!cat||x.categoria_id===cat)),aRange=rangeFor(m,cut),bRange=rangeFor(b,cut);let plot='',note='',title=q('kind').selectedOptions[0].textContent,extra='',stats='';drills={};const table=(heads,rr)=>`<div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rr.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 if(kind==='cash'){const a=cashTotals(base,...aRange),prev=cashTotals(base,...bRange),s=cashSeries(base,months,cut);stats=[['Entradas',a.income,prev.income],['Saídas pagas',a.expense,prev.expense],['Resultado',a.income-a.expense,prev.income-prev.expense]].map(([name,x,y])=>`<div><span>${name}</span><b>${money(x)}</b><small>${esc(change(x,y))}</small></div>`).join('');plot=seriesChart(s,cashKeys,{line:q('style').value==='lines',id:'cash',title});drills.cash=(i,k)=>dated(base,...rangeFor(months[i],cut)).filter(x=>k==='income'?x.tipo==='entrada':['saida','pagamento_fatura'].includes(x.tipo)&&x.forma!=='credito');note='Recebimentos e pagamentos pela data efetiva; faturas entram apenas quando pagas. Transferências e investimentos não entram no consumo. O resultado é do período, não o saldo bancário.';}
 if(['categories','sources'].includes(kind)){const income=kind==='sources',tp=income?'entrada':'saida',basis=income?'cash':'due',ar=dated(base,...aRange,basis).filter(x=>x.tipo===tp),br=dated(base,...bRange,basis).filter(x=>x.tipo===tp),ga=groupAmounts(ar,x=>categoryName(x.categoria_id)),gb=groupAmounts(br,x=>categoryName(x.categoria_id)),names=[...new Set([...ga,...gb].map(x=>x.name))],gs=names.map(name=>({name,a:ga.find(x=>x.name===name)?.value||0,b:gb.find(x=>x.name===name)?.value||0})).sort((x,y)=>y.a-x.a);plot=pairedGroups(gs,m,b,[monthName(m),monthName(b)]);drills.compare=i=>[...ar,...br].filter(x=>categoryName(x.categoria_id)===gs[i].name);extra=table(['Categoria / fonte',monthName(m),monthName(b),'Variação'],gs.map(g=>[g.name,money(g.a),money(g.b),change(g.a,g.b)]));note=income?'Receitas efetivamente recebidas, agrupadas por fonte. David, Carol e família identificam de quem é a receita.':'Despesas e parcelas pelo vencimento, pagas ou pendentes. Pagamentos de fatura não são somados novamente.';if(income){const payers=groupAmounts(ar,x=>D.fin_planos.find(p=>p.id===x.plano_id)?.dados?.pagador||'Não informado');extra+='<h3>Quem pagou no mês principal</h3>'+table(['Pagador','Recebido'],payers.map(p=>[p.name,money(p.value)]));}}
 if(kind==='evolution'){const selected=D.categorias.find(c=>c.id===cat),tp=selected?.tipo||'saida',basis=tp==='entrada'?'cash':'due',s=months.map(key=>({key,label:shortMonth(key),value:sum(dated(base,...rangeFor(key,cut),basis).filter(x=>x.tipo===tp))}));plot=seriesChart(s,[{key:'value',name:selected?.nome||(tp==='saida'?'Todas as despesas':'Receitas'),color:'#2563eb'}],{line:true,id:'evolution',title});drills.evolution=i=>dated(base,...rangeFor(months[i],cut),basis).filter(x=>x.tipo===tp);note='Escolha uma categoria para acompanhar a evolução. Despesas usam vencimento; receitas usam recebimento efetivo.';}
 if(kind==='people'){const people=[...D.pessoas,{id:'',nome:'Família'}].filter(p=>person==='all'||p.id===person),s=months.map(key=>({key,label:shortMonth(key),...Object.fromEntries(people.map((p,i)=>['p'+i,sum(dated(base,...rangeFor(key,cut),'due').filter(x=>x.tipo==='saida'&&(x.pessoa_id||'')===p.id))]))}));plot=seriesChart(s,people.map((p,i)=>({key:'p'+i,name:p.nome,color:palette[i]})),{line:q('style').value==='lines',id:'people',title});drills.people=(i,k)=>dated(base,...rangeFor(months[i],cut),'due').filter(x=>x.tipo==='saida'&&(x.pessoa_id||'')===people[Number(k.slice(1))]?.id);note='Identifica de quem são os gastos e parcelas por vencimento. Não define quem deve pagar e não cria cobranças entre vocês.';}
 if(kind==='cards'){const ms=Array.from({length:n},(_,i)=>monthShift(m,i)),groups=invoices(rows),s=ms.map(key=>({key,label:shortMonth(key),...Object.fromEntries(D.cartoes.map((c,i)=>{const g=groups.find(g=>g.month===key&&g.cartao_id===c.id);return ['c'+i,person==='all'&&!cat?(g?.remaining||0):sum(dated(base,...rangeFor(key),'due').filter(x=>x.forma==='credito'&&x.cartao_id===c.id))];}))}));plot=seriesChart(s,D.cartoes.map((c,i)=>({key:'c'+i,name:c.nome,color:palette[i%palette.length]})),{id:'cards',title});drills.cards=(i,k)=>dated(base,...rangeFor(ms[i]),'due').filter(x=>x.forma==='credito'&&x.cartao_id===D.cartoes[Number(k.slice(1))]?.id);note=person==='all'&&!cat?'Faturas em aberto, após os pagamentos registrados. Meses completos a partir do mês escolhido.':'Compras atribuídas à pessoa/categoria, sem ratear os pagamentos da fatura. Meses completos.';}
 if(kind==='budgets'){const bs=D.fin_orcamentos.filter(x=>x.mes===m+'-01'&&(!cat||cat===x.categoria_id));const gs=bs.map(b=>({name:categoryName(b.categoria_id),a:sum(dated(base,...rangeFor(m),'due').filter(x=>x.tipo==='saida'&&x.categoria_id===b.categoria_id)),b:Number(b.valor)}));plot=pairedGroups(gs,m,b,['Comprometido','Orçamento']);drills.compare=i=>dated(base,...rangeFor(m),'due').filter(x=>x.tipo==='saida'&&x.categoria_id===bs[i].categoria_id);note='Mês completo: despesas pagas e pendentes, incluindo parcelas. Orçamento é da família inteira; o filtro de pessoa restringe apenas o gasto.';extra=table(['Categoria','Comprometido','Orçamento','Restante'],gs.map(g=>[g.name,money(g.a),money(g.b),money(g.b-g.a)]));}
 if(kind==='goals'){const goals=D.fin_metas.filter(g=>person==='all'||(g.pessoa_id||'')===person),ids=new Set(goals.map(g=>g.id));const s=months.map(key=>({key,label:shortMonth(key),value:reserves(rows,dayInMonth(key,cut)).filter(r=>ids.has(r.meta_id)).reduce((s,r)=>s+r.value,0),aporte:sum(dated(rows,...rangeFor(key,cut)).filter(x=>ids.has(x.meta_id)&&['aporte','reserva'].includes(x.tipo))),retirada:sum(dated(rows,...rangeFor(key,cut)).filter(x=>ids.has(x.meta_id)&&['resgate','liberacao'].includes(x.tipo)))}));plot=seriesChart(s,[{key:'value',name:'Total reservado',color:'#2563eb'}],{line:true,id:'goals',title,detail:false});extra=seriesChart(s,[{key:'aporte',name:'Aportes e reservas',color:'#059669'},{key:'retirada',name:'Retiradas',color:'#e53945'}],{id:'goal-flow',title:'Movimentação dos objetivos'});drills['goal-flow']=(i,k)=>dated(rows,...rangeFor(months[i],cut)).filter(x=>ids.has(x.meta_id)&&(k==='aporte'?['aporte','reserva']:['resgate','liberacao']).includes(x.tipo));const rs=reserves(rows,aRange[1]);extra+=goals.map(g=>{const saved=rs.filter(r=>r.meta_id===g.id).reduce((s,r)=>s+r.value,0);return `<div class="goal-mini"><b>${esc(g.nome)}</b><span>${money(saved)} de ${money(g.valor_alvo)}</span><div class="progress"><div style="width:${Math.max(0,Math.min(100,saved/g.valor_alvo*100))}%"></div></div></div>`;}).join('');note='Reservas são parte do patrimônio. Aportes e retiradas aparecem separados. Filtro por pessoa considera o dono do objetivo; categoria não se aplica.';}
 q('title').textContent=title;q('note').textContent=`${note} ${['cash','categories','sources','evolution','people','goals'].includes(kind)?`Período principal: ${aRange[0].split('-').reverse().join('/')} a ${aRange[1].split('-').reverse().join('/')}. Comparação: ${bRange[0].split('-').reverse().join('/')} a ${bRange[1].split('-').reverse().join('/')}.`:''} ${person!=='all'&&kind==='cash'?'Pagamentos de fatura seguem a identificação do pagamento, sem divisão automática pelas compras.':''}`;q('stats').innerHTML=stats;q('plot').innerHTML=plot||'<div class="chart-empty">Nenhum registro para estes filtros.</div>';q('extra').innerHTML=extra;
 }
 host.querySelectorAll('input,select').forEach(el=>el.addEventListener('change',()=>{if(el===q('preset')||el===q('month')){if(q('preset').value!=='custom')q('compare').value=monthShift(q('month').value,q('preset').value==='year'?-12:-1);}if(el===q('compare'))q('preset').value='custom';run();}));
 const drill=e=>{const el=e.target.closest('[data-drill]');if(el&&drills[el.dataset.drill])showRecords(drills[el.dataset.drill](Number(el.dataset.index),el.dataset.series));};host.addEventListener('click',drill);host.addEventListener('keydown',e=>{if(e.target.matches('[data-drill]')&&['Enter',' '].includes(e.key)){e.preventDefault();drill(e);}});run();
}
